    vp.rulerOrigin = RulerOrigin.PAGE_ORIGIN;
    doc.zeroPoint = [0, 0];
    var dp = doc.documentPreferences;
    dp.facingPages = false;
    dp.pageWidth = DATA.pages[0].w;
